(function () { 'use strict'; const THRESHOLDS = { LCP: { good: 2500, poor: 4000 }, INP: { good: 200, poor: 500 }, CLS: { good: 0.1, poor: 0.25 }, FCP: { good: 1800, poor: 3000 }, TTFB: { good: 800, poor: 1800 }, }; function getRating(name, value) { const threshold = THRESHOLDS[name]; if (!threshold) return 'unknown'; if (value <= threshold.good) return 'good'; if (value <= threshold.poor) return 'needs-improvement'; return 'poor'; } function reportWebVital(name, value, rating) { const roundedValue = Math.round(name === 'CLS' ? value * 1000 : value); if (typeof gtag === 'function') { try { gtag('event', name, { event_category: 'Web Vitals', event_label: window.location.pathname, value: roundedValue, non_interaction: true, metric_rating: rating, }); } catch (e) { } } if (navigator.sendBeacon) { try { const data = JSON.stringify({ n: name, v: roundedValue, r: rating, p: window.location.pathname, t: Date.now(), }); navigator.sendBeacon('/api/metrics', data); } catch (e) { } } if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') { const emoji = rating === 'good' ? '\u2705' : rating === 'needs-improvement' ? '\u26A0\uFE0F' : '\u274C'; console.log(`[WebVital] ${emoji} ${name}: ${roundedValue} (${rating})`); } } function observeLCP() { try { new PerformanceObserver((entryList) => { const entries = entryList.getEntries(); if (entries.length > 0) { const lastEntry = entries[entries.length - 1]; const value = lastEntry.renderTime || lastEntry.loadTime; if (value) { reportWebVital('LCP', value, getRating('LCP', value)); } } }).observe({ type: 'largest-contentful-paint', buffered: true }); } catch (e) { } } function observeINP() { if (!('PerformanceEventTiming' in window) || !('interactionId' in PerformanceEventTiming.prototype)) { return; } try { let maxINP = 0; const observer = new PerformanceObserver((entryList) => { for (const entry of entryList.getEntries()) { if (entry.interactionId > 0) { const duration = entry.processingEnd - entry.startTime; if (duration > maxINP) { maxINP = duration; } } } }); observer.observe({ type: 'event', buffered: true, durationThreshold: 16 }); const reportINP = () => { if (maxINP > 0) { reportWebVital('INP', maxINP, getRating('INP', maxINP)); } }; ['visibilitychange', 'pagehide'].forEach((event) => { document.addEventListener(event, () => { if (document.visibilityState === 'hidden') { reportINP(); } }, { once: true }); }); } catch (e) { } } function observeCLS() { try { let clsValue = 0; let sessionEntries = []; new PerformanceObserver((entryList) => { for (const entry of entryList.getEntries()) { if (!entry.hadRecentInput) { sessionEntries.push(entry); } } let sessionValue = 0; for (const entry of sessionEntries) { sessionValue += entry.value; } if (sessionValue > clsValue) { clsValue = sessionValue; } }).observe({ type: 'layout-shift', buffered: true }); ['visibilitychange', 'pagehide'].forEach((event) => { document.addEventListener(event, () => { if (document.visibilityState === 'hidden') { reportWebVital('CLS', clsValue, getRating('CLS', clsValue)); } }, { once: true }); }); } catch (e) { } } function observeFCP() { try { new PerformanceObserver((entryList) => { const entries = entryList.getEntries(); if (entries.length > 0) { const value = entries[0].startTime; reportWebVital('FCP', value, getRating('FCP', value)); } }).observe({ type: 'paint', buffered: true }); } catch (e) { } } function observeTTFB() { try { const navEntry = performance.getEntriesByType('navigation')[0]; if (navEntry) { const ttfb = navEntry.responseStart - navEntry.requestStart; if (ttfb > 0) { reportWebVital('TTFB', ttfb, getRating('TTFB', ttfb)); } } new PerformanceObserver((entryList) => { for (const entry of entryList.getEntries()) { const ttfb = entry.responseStart - entry.requestStart; if (ttfb > 0) { reportWebVital('TTFB', ttfb, getRating('TTFB', ttfb)); } } }).observe({ type: 'navigation', buffered: true }); } catch (e) { } } function logPerformanceSummary() { window.addEventListener('load', () => { setTimeout(() => { const navTiming = performance.getEntriesByType('navigation')[0]; if (!navTiming) return; const metrics = { 'DNS': (navTiming.domainLookupEnd - navTiming.domainLookupStart).toFixed(0), 'TCP': (navTiming.connectEnd - navTiming.connectStart).toFixed(0), 'Request': (navTiming.responseStart - navTiming.requestStart).toFixed(0), 'Response': (navTiming.responseEnd - navTiming.responseStart).toFixed(0), 'DOM Ready': (navTiming.domContentLoadedEventEnd - navTiming.fetchStart).toFixed(0), 'Page Load': (navTiming.loadEventEnd - navTiming.fetchStart).toFixed(0), 'Total Resources': performance.getEntriesByType('resource').length, }; if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') { console.log('[Perf] 页面加载时间线 (ms):', metrics); } if (typeof gtag === 'function') { gtag('event', 'page_load_performance', { event_category: 'Performance', event_label: window.location.pathname, ...metrics, non_interaction: true, }); } }, 1000); }); } function initErrorCapture() { window.addEventListener('error', (event) => { if (typeof gtag === 'function') { gtag('event', 'exception', { description: `${event.message} at ${event.filename}:${event.lineno}:${event.colno}`, fatal: false, }); } console.error('[GlobeTimeZone Error]', event.message, { file: event.filename, line: event.lineno, col: event.colno, timestamp: new Date().toISOString(), }); }); window.addEventListener('unhandledrejection', (event) => { const reason = event.reason instanceof Error ? event.reason.message : String(event.reason); if (typeof gtag === 'function') { gtag('event', 'exception', { description: `Unhandled Promise: ${reason}`, fatal: false, }); } console.error('[GlobeTimeZone UnhandledRejection]', reason, { timestamp: new Date().toISOString(), }); }); } function startMonitoring() { observeLCP(); observeINP(); observeCLS(); observeFCP(); observeTTFB(); logPerformanceSummary(); initErrorCapture(); } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', startMonitoring); } else { startMonitoring(); }
})();